/// <summary>
/// Inserts TMS processing status.
/// </summary>
/// <param name = "_orderType">Order type.</param>
/// <param name = "_docNumber">Document number.</param>
/// <param name = "_executionMode">Execution mode.</param>
public static void insertTMSProcessingStatus(METTMSOrderType _orderType, 
                                             METOrderNumber _docNumber,
                                             METTMSEngineExecutionMode _executionMode)
{
    METTMSProcessingStatus tmsProcessingStatus;

    tmsProcessingStatus = METTMSProcessingStatus::find(_orderType, _docNumber, _executionMode);

    if (!tmsProcessingStatus)
    {
        ttsbegin;
        tmsProcessingStatus.OrderType = _orderType;
        tmsProcessingStatus.DocumentNumber = _docNumber;
        tmsProcessingStatus.ExecutionMode = _executionMode;
        tmsProcessingStatus.Status = METTMSSyncStatus::ToBeProcessed;

        tmsProcessingStatus.insert();
        ttscommit;
    }
}

/// <summary>
/// Gets table <c>METTMSProcessingStatus</c>.
/// </summary>
/// <param name = "_orderType">Order type.</param>
/// <param name = "_docNumber">Document number.</param>
/// <param name = "_executionMode">Execution mode.</param>
/// <param name = "_forUpdate"></param>
/// <returns>Table <c>METTMSProcessingStatus</c>.</returns>
public static METTMSProcessingStatus find(METTMSOrderType _orderType,
                                          METOrderNumber _docNumber, 
                                          METTMSEngineExecutionMode _executionMode,
                                          boolean _forUpdate = false)
{
    METTMSProcessingStatus tmsProcessingStatus;

    tmsProcessingStatus.selectForUpdate(_forUpdate);

    select firstonly tmsProcessingStatus
        where tmsProcessingStatus.OrderType == _orderType
        &&    tmsProcessingStatus.DocumentNumber == _docNumber
        &&    tmsProcessingStatus.ExecutionMode == _executionMode;

    return tmsProcessingStatus;
}
